```json
{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "A tabela dá as cadeiras por modelo e cor, mas a taxa de defeito depende só do modelo. Por isso, calcule o defeito de cada modelo dentro de cada cor e some por cor. As cadeiras boas são o total da cor menos as com defeito. A pergunta pede duas linhas (D e B) e duas colunas (P e V).",
   "motivo": "Diz de forma explícita o formato do que é pedido."
  },
  {
   "campo": "resolucao.antes.formulas",
   "depois": [
    "defeituosas = taxa × quantidade (2% de 500 = 0,02 × 500)",
    "boas = total da cor − defeituosas da cor"
   ],
   "motivo": "Mostra como a porcentagem vira conta."
  },
  {
   "campo": "resolucao.passos[1].conta",
   "depois": "2% de 500 = 10 | 5% de 400 = 20 | 8% de 250 = 20",
   "motivo": "Separa as contas em itens legíveis."
  },
  {
   "campo": "resolucao.passos[1].porque",
   "depois": "Aplique a taxa de cada modelo à quantidade preta desse modelo. Depois some: 10 + 20 + 20 = 50 pretas com defeito.",
   "motivo": "Deixa claro o que a soma representa."
  },
  {
   "campo": "resolucao.passos[2].conta",
   "depois": "2% de 200 = 4 | 5% de 220 = 11 | 8% de 300 = 24",
   "motivo": "Mesmo formato do passo anterior."
  },
  {
   "campo": "resolucao.passos[2].porque",
   "depois": "Mesmo raciocínio, agora com a coluna V. Soma: 4 + 11 + 24 = 39 vermelhas com defeito.",
   "motivo": "Deixa claro o que a soma representa."
  },
  {
   "campo": "resolucao.passos[3].conta",
   "depois": "P: 1150 − 50 = 1100 | V: 720 − 39 = 681",
   "motivo": "Sem mudança de fato; apenas confirma o formato."
  },
  {
   "campo": "resolucao.passos[4].porque",
   "depois": "Só a alternativa C traz D = 50 e 39 e B = 1100 e 681.",
   "motivo": "Liga o resultado à letra com a justificativa."
  },
  {
   "campo": "resolucao.quadro",
   "depois": [
    {"linha": "Pretas (P):", "nota": "taxa de cada modelo × quantidade"},
    {"linha": "0,02 × 500 = 10", "nota": "M1 com defeito"},
    {"linha": "0,05 × 400 = 20", "nota": "M2 com defeito"},
    {"linha": "0,08 × 250 = 20", "nota": "M3 com defeito"},
    {"linha": "D_P = 10 + 20 + 20 = 50", "nota": "pretas com defeito"},
    {"linha": "Vermelhas (V):", "nota": "mesma conta"},
    {"linha": "0,02 × 200 = 4", "nota": "M1 com defeito"},
    {"linha": "0,05 × 220 = 11", "nota": "M2 com defeito"},
    {"linha": "0,08 × 300 = 24", "nota": "M3 com defeito"},
    {"linha": "D_V = 4 + 11 + 24 = 39", "nota": "vermelhas com defeito"},
    {"linha": "500 + 400 + 250 = 1150", "nota": "total de pretas"},
    {"linha": "200 + 220 + 300 = 720", "nota": "total de vermelhas"},
    {"linha": "B_P = 1150 − 50 = 1100", "nota": "pretas boas"},
    {"linha": "B_V = 720 − 39 = 681", "nota": "vermelhas boas"}
   ],
   "motivo": "Inclui as somas dos totais, antes puladas, e agrupa por cor."
  }
 ],
